import { createVueform } from '@vueform/primevue/full'
import PrimeVue from 'primevue/config'
import { createApp } from 'vue'
import App from './App.vue'
// Barrel generated by `vueform copy all --dir src/vueform` (the runner does this).
import localComponents from './vueform.js'
import '@vueform/primevue/theme.css'

createApp(App)
  .use(PrimeVue, { unstyled: true })
  .use(createVueform({ components: { ...localComponents } }))
  .mount('#app')
